const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
const [ia, ib, fa, fb] = input;

// a = 1 se a lâmpada A precisa trocar de estado, b = 1 se a lâmpada B precisa trocar
const a = ia ^ fa;
const b = ib ^ fb;

// C1 toggla apenas A (x vezes), C2 toggla A e B (y vezes).
// Condições: (x + y) % 2 === a e y % 2 === b. Minimizar x + y.
// a=0,b=0 -> 0;  a=0,b=1 -> precisa y ímpar e x ímpar -> 2;  a=1,b=0 -> C1 apenas -> 1;  a=1,b=1 -> C2 apenas -> 1
const ans = (a === 0 && b === 0) ? 0 : (a === 0 ? 2 : 1);

console.log(ans);
